using System; using System.Data; using System.Data.SqlClient; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp { public partial class ResetPasswordPage : BasePage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object ResetPasswordToken(string token, string newPassword, string confirmPassword) { SecurityHelper.ValidateCsrfOrThrow(); if (string.IsNullOrWhiteSpace(token) || string.IsNullOrWhiteSpace(newPassword) || !string.Equals(newPassword, confirmPassword, StringComparison.Ordinal)) return new { success = false, message = "Invalid reset request." }; if (!PasswordHasher.MeetsPasswordPolicy(newPassword)) return new { success = false, message = "Password does not meet policy requirements." }; var table = DbHelper.ExecuteDataTable("SELECT TOP 50 ResetTokenID, UserID, TokenHash, ExpiresAt, IsUsed FROM PasswordResetTokens WHERE IsUsed = 0 ORDER BY CreatedDate DESC", CommandType.Text); DataRow matched = null; foreach (DataRow row in table.Rows) if (PasswordHasher.VerifyPassword(token, row["TokenHash"].ToString())) { matched = row; break; } if (matched == null || Convert.ToBoolean(matched["IsUsed"]) || Convert.ToDateTime(matched["ExpiresAt"]) < DateTime.UtcNow) return new { success = false, message = "Reset token is invalid or expired." }; var userId = Convert.ToInt32(matched["UserID"]); DbHelper.ExecuteNonQuery("UPDATE Users SET PasswordHash = @PasswordHash, MustChangePassword = 0 WHERE UserID = @UserID", CommandType.Text, new SqlParameter("@PasswordHash", PasswordHasher.HashPassword(newPassword)), new SqlParameter("@UserID", userId)); DbHelper.ExecuteNonQuery("UPDATE PasswordResetTokens SET IsUsed = 1, UsedDate = GETUTCDATE() WHERE ResetTokenID = @ResetTokenID", CommandType.Text, new SqlParameter("@ResetTokenID", matched["ResetTokenID"])); SessionManager.RevokeUserSessions(userId, SessionManager.GetCurrentUserIdOrNull() ?? userId, "Password reset"); AuditLogger.Log(userId, "PASSWORD_RESET", "Authentication", "ResetPassword.aspx", userId.ToString(), null, "Password reset completed"); return new { success = true, message = "Password reset successful. Please login again." }; } } }
